public class MonthlyAttendanceAnnouncer{static class GymMember{int sessions;void displayInfo(StringBuilder s){s.append("Standard | Sessions: ").append(sessions);}}static class PremiumMember extends GymMember{String trainer;PremiumMember(String t){trainer=t;}@Override void displayInfo(StringBuilder s){s.append("Premium | Trainer: ").append(trainer).append(" | Sessions: ").append(sessions);}}static String batchPrint(GymMember[] a){StringBuilder s=new StringBuilder();for(GymMember m:a){m.displayInfo(s);if(m instanceof PremiumMember)s.append(" [Trainer via downcast: ").append(((PremiumMember)m).trainer).append("]");s.append(" | ");}return s.toString();}}